import { ValidationPipe, VersioningType } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import type { NestExpressApplication } from '@nestjs/platform-express';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import * as express from 'express';
import { UrlApiConfigService } from './config/url-api/url-api.service';
import { AppModule } from '@/app.module';

/**
 * Sets up Swagger/OpenAPI documentation for the application.
 * @param app The NestJS Express application instance
 */
function setupSwagger(app: NestExpressApplication): void {
  const { urlApi } = app.get(UrlApiConfigService);
  const config = new DocumentBuilder()
    .setTitle('MESX Plant Hierarchy Setup Backend API')
    .setDescription('MESX Plant Hierarchy Setup Backend API documentation')
    .addServer(urlApi, 'pre-production')
    .setVersion('1.0')
    .addBearerAuth()
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document, {
    jsonDocumentUrl: 'api-json',
    swaggerOptions: {
      persistAuthorization: true,
    },
  });
}

/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestExpressApplication>(AppModule);

  app.use(express.json({ type: ['application/json', 'application/cloudevents+json'] }));
  // Global validation pipe
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  app.enableCors({
    allowedHeaders: 'Content-Type,Authorization',
    origin: '*',
  });

  app.enableVersioning({
    type: VersioningType.URI,
  });

  setupSwagger(app);

  await app.listen(3000);
}

void bootstrap();

