import {
  CreateEquipmentClassPropertyDto,
  UpdateEquipmentClassPropertyDto,
} from './dtos/equipment-class-property.dto';
import { buildMethodPath } from '@/common/invokes/build-method-path';
import { invokeService } from '@/common/invokes/invoke-service';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class EquipmentClassPropertyService {
  private readonly logger = new AppLogger(EquipmentClassPropertyService.name);
  private readonly daprClient: DaprClient;
  private readonly targetAppId: string;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.targetAppId
      = this.daprConfigService.plantHierarchyApiAppId ?? 'mesx-plant-hierarchy-api';
    this.daprClient = new DaprClient();
  }

  public async findByClassId(
    classId: number,
    language?: string,
  ): Promise<Array<EquipmentClassPropertyResponseDto>> {
    const method = buildMethodPath(`isa95-equipment-model/equipment-class-properties/by-class/${classId}`, { language });

    const result = await invokeService<Array<EquipmentClassPropertyResponseDto>>(
      { context: { service: 'EquipmentClassPropertyService', method: 'findByClassId' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.GET, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );
    return result ?? [];
  }

  public async create(
    createEquipmentClassPropertyDto: CreateEquipmentClassPropertyDto,
  ): Promise<EquipmentClassPropertyResponseDto> {
    const method = 'isa95-equipment-model/equipment-class-properties';

