    return await invokeService<PhysicalAssetClass | undefined>(
      { context: { service: PhysicalAssetClassService.name, method: 'update' }, customLogger: this.logger, daprClient: this.daprClient },
      {
        method: HttpMethod.PATCH,
        serviceAppId: this.targetAppId,
        serviceMethod: method,
        data: structuredClone(payload),
        options: buildJsonInvokeOptions(),
      },
      { throwIfError: true },
    );
  }

  public async replaceProperties(
    id: number,
    payload: { propertyIds: Array<number> },
  ): Promise<PhysicalAssetClass | undefined> {
    const method
      = `${physicalAssetClassesServicePath}/${id}/properties`;

    this.logger.log(`Replacing physical asset class properties for class ${id}`);

    return await invokeService<PhysicalAssetClass | undefined>(
