  public async delete(id: number): Promise<void> {
    const method
      = `${physicalAssetClassesServicePath}/${id}`;

    this.logger.log(`Deleting physical asset class ${id}`);

    await invokeService<void>(
      { context: { service: PhysicalAssetClassService.name, method: 'delete' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.DELETE, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );
  }

  private requireUpstreamResponse<T>(
    response: T | undefined,
    servicePath: string,
  ): T {
    if (response === undefined) {
      throw new BadGatewayException(
        `Plant hierarchy upstream service returned no payload for ${servicePath}`,
      );
    }

    return response;
  }
