interface ServiceWithDaprClient {
  daprClient: { invoker: { invoke: jest.Mock } }
}

/**
 * Replaces a service Dapr client with a Jest invoke mock.
 * @param service - Service instance whose Dapr client should be mocked.
 * @param invokeMock - Mock implementation for Dapr invocations.
 */
function attachInvokeMock(service: unknown, invokeMock: jest.Mock): void {
  (service as ServiceWithDaprClient).daprClient = {
    invoker: {
      invoke: invokeMock,
    },
  };
}

