      expect(exception.getResponse()).toBe('{"message":"Missing asset"}');
    }
  });

  it('omits authorization when TOKEN is not set', async () => {
    delete process.env.TOKEN;
    invokeMock.mockResolvedValue([]);

    await physicalAssetService.getPhysicalAssetDetailsFlat({ plant: 'TN01' });

    expect(invokeMock).toHaveBeenCalledWith(
      'mesx-plant-hierarchy-api',
      'v1/isa95-physical-asset-model/getPhysicalAssetDetailsFlat?plant=TN01',
      HttpMethod.GET,
      undefined,
      {},
    );
  });
});

