import { Injectable } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { buildInvokeOptions } from '@/common/invokes/build-invoke-options';
import { buildMethodPath } from '@/common/invokes/build-method-path';
import { invokeService } from '@/common/invokes/invoke-service';
import { AppLogger } from '@/common/logger/app-logger';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import type { CreatePhysicalAssetWithDetailsDto } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/create-physical-asset-with-details.dto';
import type { GetPhysicalAssetDetailsFlatQueryDto } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/get-physical-asset-details-flat.query.dto';
import type { PhysicalAssetParentOption } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/physical-asset-parent-option.dto';
import type { PhysicalAssetParentOptionsQueryDto } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/physical-asset-parent-options.query.dto';
import type { PhysicalAsset } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/physical-asset.dto';
import type { SavePhysicalAssetDetailsDto } from '@/modules/isa95-physical-asset-model/physical-asset/dtos/save-physical-asset-details.dto';

const contentTypeHeader = 'Content-Type';
const jsonContentType = 'application/json';
const physicalAssetModelServicePath = 'v1/isa95-physical-asset-model';
const physicalAssetServicePath = `${physicalAssetModelServicePath}/physical-asset`;

interface NormalizedPhysicalAssetClassPropertiesPayload {
  physicalAssetClassId: number
  properties: Record<string, unknown>
}

interface NormalizePhysicalAssetDetailsOptions {
  trimBlankText?: boolean
}

/**
 * Removes keys whose values are undefined from a payload.
 * @param payload - The payload to remove undefined values from.
 * @returns A new payload containing only defined values.
 */
function omitUndefinedValues(
  payload: Record<string, unknown>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(payload).filter(([, value]) => value !== undefined),
  );
}

/**
 * Builds Dapr invoke options with JSON content headers.
 * @returns Dapr invoke options with authorization and JSON content headers.
 */
function buildJsonInvokeOptions(): { headers: Record<string, unknown> } {
  const options = buildInvokeOptions();

  return {
    headers: {
      ...options.headers,
      [contentTypeHeader]: jsonContentType,
    },
  };
}

/**
 * Normalizes physical asset class property payloads for upstream persistence.
 * @param payload - The physical asset details payload to normalize.
 * @returns Valid class property payloads, or undefined when none are present.
 */
function normalizePhysicalAssetClassProperties(
  payload: SavePhysicalAssetDetailsDto,
): Array<NormalizedPhysicalAssetClassPropertiesPayload> | undefined {
  const classProperties = payload.classProperties;
  if (!Array.isArray(classProperties) || classProperties.length === 0) {
    return undefined;
  }

  return classProperties.reduce<Array<NormalizedPhysicalAssetClassPropertiesPayload>>(
    (accumulator, entry) => {
      const physicalAssetClassId = entry.physicalAssetClassId;
      if (
        typeof physicalAssetClassId !== 'number'
        || !Number.isFinite(physicalAssetClassId)
        || physicalAssetClassId <= 0
      ) {
        return accumulator;
      }

      accumulator.push({
        physicalAssetClassId,
        properties: entry.properties,
      });

      return accumulator;
    },
    [],
  );
}

/**
 * Normalizes a physical asset details payload before invoking the upstream service.
 * @param payload - The physical asset details payload to normalize.
 * @param options - Optional normalization behavior.
 * @returns Plain JSON payload fields expected by the upstream service.
 */
function normalizePhysicalAssetDetailsPayload(
  payload: SavePhysicalAssetDetailsDto,
  options?: NormalizePhysicalAssetDetailsOptions,
): Record<string, unknown> {
  const trimBlankText = options?.trimBlankText === true;
  const normalizeText = (value: string | undefined): string | undefined => {
    if (!trimBlankText || value === undefined) {
      return value;
    }

    const trimmedValue = value.trim();
    return trimmedValue.length > 0 ? trimmedValue : undefined;
  };

  return omitUndefinedValues({
    code: normalizeText(payload.code),
    description: normalizeText(payload.description),
    erpSource: normalizeText(payload.erpSource),
    parentPhysicalAssetId: payload.parentPhysicalAssetId,
    physicalAssetLocation: payload.physicalAssetLocation,
    effectiveStartDate: payload.effectiveStartDate,
    effectiveEndDate: payload.effectiveEndDate,
    classIds: payload.classIds,
    properties: payload.properties,
    propertiesPhysicalAssetClassId: payload.propertiesPhysicalAssetClassId,
    classProperties: normalizePhysicalAssetClassProperties(payload),
  });
}

@Injectable()
export class PhysicalAssetService {
  private readonly logger = new AppLogger(PhysicalAssetService.name);
  private readonly daprClient: DaprClient;
  private readonly targetAppId: string;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.targetAppId
      = this.daprConfigService.plantHierarchyApiAppId ?? 'mesx-plant-hierarchy-api';
    this.daprClient = new DaprClient();
  }

  public async getPhysicalAssetDetailsFlat(
    query: GetPhysicalAssetDetailsFlatQueryDto,
  ): Promise<unknown> {
    const method = buildMethodPath(
      `${physicalAssetModelServicePath}/getPhysicalAssetDetailsFlat`,
      {
        plant: query.plant,
        limit: query.limit,
        offset: query.offset,
      },
    );

    this.logger.log(`Fetching physical asset details for plant ${query.plant}`);

    return await invokeService<unknown>(
      { context: { service: PhysicalAssetService.name, method: 'getPhysicalAssetDetailsFlat' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.GET, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );
  }

  public async getParentOptions(
    query: PhysicalAssetParentOptionsQueryDto,
  ): Promise<Array<PhysicalAssetParentOption>> {
    const method = buildMethodPath(
      `${physicalAssetServicePath}/parent-options`,
      {
        plant: query.plant,
        excludePhysicalAssetId: query.excludePhysicalAssetId,
      },
    );

    this.logger.log(`Fetching physical asset parent options for plant ${query.plant}`);

    const result = await invokeService<Array<PhysicalAssetParentOption>>(
      { context: { service: PhysicalAssetService.name, method: 'getParentOptions' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.GET, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );

    return result ?? [];
  }

  public async createWithDetails(
    payload: CreatePhysicalAssetWithDetailsDto,
  ): Promise<PhysicalAsset | undefined> {
    const method
      = `${physicalAssetServicePath}/create-with-details`;
    const normalizedPayload = {
      ...normalizePhysicalAssetDetailsPayload(payload),
      plant: payload.plant,
    };

    this.logger.log('Creating physical asset with details');

    return await invokeService<PhysicalAsset | undefined>(
      { context: { service: PhysicalAssetService.name, method: 'createWithDetails' }, customLogger: this.logger, daprClient: this.daprClient },
      {
        method: HttpMethod.POST,
        serviceAppId: this.targetAppId,
        serviceMethod: method,
        data: normalizedPayload,
        options: buildJsonInvokeOptions(),
      },
      { throwIfError: true },
    );
  }

  public async findOneWithRelations(
    id: number,
  ): Promise<unknown> {
    const method
      = `${physicalAssetServicePath}/${id}/with-relations`;

    this.logger.log(`Fetching physical asset ${id} with relations`);

    return await invokeService<unknown>(
      { context: { service: PhysicalAssetService.name, method: 'findOneWithRelations' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.GET, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );
  }

  public async updateDetails(
    id: number,
    payload: SavePhysicalAssetDetailsDto,
  ): Promise<PhysicalAsset | undefined> {
    const method
      = `${physicalAssetServicePath}/${id}/save-details`;
    const normalizedPayload = normalizePhysicalAssetDetailsPayload(payload, {
      trimBlankText: true,
    });

    this.logger.log(`Saving physical asset details for asset ${id}`);

    return await invokeService<PhysicalAsset | undefined>(
      { context: { service: PhysicalAssetService.name, method: 'updateDetails' }, customLogger: this.logger, daprClient: this.daprClient },
      {
        method: HttpMethod.PATCH,
        serviceAppId: this.targetAppId,
        serviceMethod: method,
        data: normalizedPayload,
        options: buildJsonInvokeOptions(),
      },
      { throwIfError: true },
    );
  }

  public async delete(id: number): Promise<void> {
    const method = `${physicalAssetServicePath}/${id}`;

    this.logger.log(`Deleting physical asset ${id}`);

    await invokeService<void>(
      { context: { service: PhysicalAssetService.name, method: 'delete' }, customLogger: this.logger, daprClient: this.daprClient },
      { method: HttpMethod.DELETE, serviceAppId: this.targetAppId, serviceMethod: method },
      { throwIfError: true },
    );
  }
}

